content = DR.read_text(encoding="utf-8")
lines = content.split("\n")
fm_end = -1
if lines and lines[0] == "---":
    for i in range(1, len(lines)):
        if lines[i] == "---":
            fm_end = i
            break

if fm_end == -1:
    new_content = NEW + content.lstrip("\n")
else:
    fm_block = "\n".join(lines[:fm_end+1]) + "\n"
    body = "\n".join(lines[fm_end+1:])
    idx = body.find("\n## ")
    if idx == -1:
        new_content = fm_block + "\n" + NEW + body.lstrip("\n")
    else:
        new_content = fm_block + body[:idx+1] + "\n" + NEW + body[idx+1:].lstrip("\n")

DR.write_text(new_content, encoding="utf-8")
print(f"Updated {DR} ({len(new_content)} bytes)")
